import{_ as t,o as e,c as l,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"品牌一致性控制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"method/brand-consistency.md","filePath":"method/brand-consistency.md","lastUpdated":1786327499000}'),r={name:"method/brand-consistency.md"};function i(n,a,s,d,h,c){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="品牌一致性控制" tabindex="-1">品牌一致性控制 <a class="header-anchor" href="#品牌一致性控制" aria-label="Permalink to &quot;品牌一致性控制&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">待补充</p><p>这一页还没有实战内容。下面是已经确定的问题结构和待填的位置——遇到相关经验时按框架往里填。</p></div><h2 id="这一页要解决的问题" tabindex="-1">这一页要解决的问题 <a class="header-anchor" href="#这一页要解决的问题" aria-label="Permalink to &quot;这一页要解决的问题&quot;">​</a></h2><p>AI 生成的素材，在三个维度上会漂移：</p><ol><li><strong>人物漂移</strong> —— 第 3 个镜头和第 7 个镜头里，&quot;同一个人&quot;长得不一样。</li><li><strong>产品漂移</strong> —— logo 位置变了、瓶身比例变了、颜色偏了。</li><li><strong>风格漂移</strong> —— 色调、质感、光线氛围在镜头之间不统一。</li></ol><p>对品牌广告来说，第 2 条是致命的：产品画错了，整支片子作废。</p><h2 id="已知的解法方向" tabindex="-1">已知的解法方向 <a class="header-anchor" href="#已知的解法方向" aria-label="Permalink to &quot;已知的解法方向&quot;">​</a></h2><p>这三条是通用的思路，具体到某个工具怎么操作，需要实测后补充。</p><p><strong>方向一：参考图锚定。</strong> 主流图像/视频工具都支持传入参考图来约束人物或产品的外观。把同一张参考图贯穿所有镜头，是控制人物和产品漂移最直接的办法。</p><p><strong>方向二：风格描述固化。</strong> 把风格部分（色调、光线、镜头质感、胶片感）写成一段固定文本，每条 Prompt 原样带上，只改主体和动作。见 <a href="/prompts/structure">Prompt 结构通法</a> 里的五段式。</p><p><strong>方向三：后期兜底。</strong> 承认生成阶段控不住，改在调色阶段统一。全片套同一个 LUT，能救回相当一部分风格漂移。产品如果画不准，直接用真实产品图合成。</p><h2 id="待填内容" tabindex="-1">待填内容 <a class="header-anchor" href="#待填内容" aria-label="Permalink to &quot;待填内容&quot;">​</a></h2><p>按下面的结构补充，每条都要写清楚<strong>在哪个工具上、什么设置、效果如何</strong>：</p><h3 id="人物一致性" tabindex="-1">人物一致性 <a class="header-anchor" href="#人物一致性" aria-label="Permalink to &quot;人物一致性&quot;">​</a></h3><ul><li>试过的方法：</li><li>有效的：</li><li>无效的：</li><li>参数记录：</li></ul><h3 id="产品保真" tabindex="-1">产品保真 <a class="header-anchor" href="#产品保真" aria-label="Permalink to &quot;产品保真&quot;">​</a></h3><ul><li>试过的方法：</li><li>有效的：</li><li>无效的：</li><li>什么情况下必须放弃生成、改用合成：</li></ul><h3 id="风格统一" tabindex="-1">风格统一 <a class="header-anchor" href="#风格统一" aria-label="Permalink to &quot;风格统一&quot;">​</a></h3><ul><li>固定风格描述的模板：</li><li>调色兜底的做法：</li></ul><h3 id="翻车记录" tabindex="-1">翻车记录 <a class="header-anchor" href="#翻车记录" aria-label="Permalink to &quot;翻车记录&quot;">​</a></h3><ul><li>出过什么问题：</li><li>当时怎么补救的：</li><li>下次怎么预防：</li></ul><hr><p>需要的写作格式参考 <a href="/templates/prompt-card">Prompt 卡片模板</a>。</p>',23)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
